{"action": "write", "path": "duration.py", "content": "import re


_DURATION_RE = re.compile(
    r"(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?"
)

_UNIT_SECONDS = (
    ("d", 24 * 60 * 60),
    ("h", 60 * 60),
    ("m", 60),
    ("s", 1),
)


def parse_duration(s):
    """Parse a duration string such as '1h30m' into seconds."""
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    text = s.strip()
    if not text:
        raise ValueError("duration cannot be empty")

    match = _DURATION_RE.fullmatch(text)
    if match is None:
        raise ValueError("invalid duration")

    amounts = match.groups()
    if all(amount is None for amount in amounts):
        raise ValueError("invalid duration")

    total = 0
    for amount, (_, multiplier) in zip(amounts, _UNIT_SECONDS):
        if amount is not None:
            total += int(amount) * multiplier

    return total
